function decideContactQueue(current, enqueued, exactResponse, queueResponse, now) {
  const hold = reason => { throw new Error('HOLD_CONTACT_QUEUE_' + reason); };
  const option = value => typeof value === 'string' ? value : value?.name;
  if (!/^rec[A-Za-z0-9]+$/.test(current) || enqueued?.id !== current) hold('REQUEST_IDENTITY');
  const requestedAt = Date.parse(enqueued.fields?.['Contact Queued At'] ?? '');
  if (!Number.isFinite(requestedAt)) hold('REQUEST_TIMESTAMP');
  if (!Array.isArray(exactResponse?.records) || exactResponse.offset) hold('CURRENT_READ_INCOMPLETE');
  if (exactResponse.records.length === 0) return {stop: true, reason: 'record_missing'};
  if (exactResponse.records.length !== 1 || exactResponse.records[0]?.id !== current) hold('CURRENT_IDENTITY');
  const currentRow = exactResponse.records[0];
  const fields = currentRow.fields;
  if (!fields || typeof fields !== 'object' || Array.isArray(fields)) hold('CURRENT_FIELDS');
  if (option(fields['Contact Queue Status']) !== 'Queued') return {stop: true, reason: 'no_longer_queued'};
  const currentAt = Date.parse(fields['Contact Queued At'] ?? '');
  if (!Number.isFinite(currentAt)) hold('CURRENT_TIMESTAMP');
  if (currentAt !== requestedAt) return {stop: true, reason: 'request_replaced'};
  if (!Array.isArray(queueResponse?.records) || queueResponse.offset) hold('QUEUE_READ_INCOMPLETE');
  const records = queueResponse.records;
  if (records.some(r => !r || typeof r.id !== 'string' || !r.fields || typeof r.fields !== 'object')) hold('QUEUE_RECORD');
  if (new Set(records.map(r => r.id)).size !== records.length) hold('QUEUE_DUPLICATES');
  const snapshot = records.filter(r => r.id === current);
  // Two read requests can straddle a write. Never start from a missing/stale
  // queue snapshot, and never mistake that snapshot for authoritative deletion.
  if (snapshot.length === 0 || option(snapshot[0].fields['Contact Queue Status']) !== 'Queued'
      || Date.parse(snapshot[0].fields['Contact Queued At'] ?? '') !== requestedAt) {
    return {recordId: current, canStart: false, waitingBehind: 0, queueMessage: 'Waiting for the queue view to refresh'};
  }
  const activeStatuses = new Set(['Running', 'Processing', 'Queued', 'Waiting']);
  const liveRunning = records.filter(r => r.id !== current && option(r.fields['Contact Queue Status']) === 'Running')
    .filter(r => activeStatuses.has(option(r.fields['Processing Status'])))
    .filter(r => { const started = Date.parse(r.fields['Processing Started At'] || ''); return !Number.isFinite(started) || now - started < 12 * 60 * 60 * 1000; });
  const queued = records.filter(r => option(r.fields['Contact Queue Status']) === 'Queued');
  const queueTime = r => Date.parse(r.fields['Contact Queued At'] || r.createdTime || '');
  if (queued.some(r => !Number.isFinite(queueTime(r)))) hold('QUEUE_TIMESTAMP');
  queued.sort((a, b) => queueTime(a) - queueTime(b));
  const canStart = liveRunning.length === 0 && queued[0]?.id === current;
  return {recordId: current, canStart, waitingBehind: liveRunning.length + Math.max(0, queued.findIndex(r => r.id === current)), queueMessage: canStart ? 'Starting contact run' : 'Waiting for the contact run ahead of this request'};
}

