  throw new Error('A valid Airtable Lead Lists recordId is required before creating expansion workers.');
}
if (!target) {
  throw new Error('A positive expansion target is required before creating expansion workers.');
}


const batchLimit = 2500;
const remaining = Math.max(0, target - existingCount);
if (!remaining) {
  return [{ json: { recordId, runNumber: 0, totalRuns: 0, target, existingCount, alreadyComplete: true, assignedOffset: 0, assignedLimit: 0 } }];
}


// Partition the remaining target evenly so no trailing batch has fewer than five.
const candidatesNeeded = Math.max(5, remaining);
const runs = Math.ceil(candidatesNeeded / batchLimit);
const baseSize = Math.floor(candidatesNeeded / runs);
const extra = candidatesNeeded % runs;
let offset = 0;
return Array.from({ length: runs }, (_, index) => {
  const assignedLimit = baseSize + (index < extra ? 1 : 0);
