SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
SELECT pg_advisory_xact_lock_shared(64388748,1);
WITH gate AS MATERIALIZED (
 SELECT workflow_id FROM public.contact_discovery_admission_gate
 WHERE workflow_id=$5 AND enabled IS TRUE AND generation=$4::bigint
), changed AS (
 UPDATE public.contact_discovery_batch_receipt r
 SET state='submitted',request_started_at=clock_timestamp(),updated_at=clock_timestamp()
 WHERE r.batch_key=$1 AND r.owner_execution_id=$2 AND r.state='reserved' AND r.workflow_id=$5
 AND r.request_json->>'protocol'='native-discovery-receipt-v1'
 AND r.request_json->'request'=$3::jsonb
 AND EXISTS(SELECT 1 FROM gate)
 RETURNING r.*
)
SELECT 'submission_guard' AS phase,(SELECT count(*) FROM gate)::int AS gate_rows,
 count(*)::int AS changed,(jsonb_agg(to_jsonb(changed))->0) AS receipt FROM changed;

