const source = $('Normalize Expansion Record').first().json;
const response = $input.first()?.json || {};
const status = Number(response.statusCode ?? 200);
const body = response.body ?? response;
const missingReview = status === 400 && body?.error?.status === 'INVALID_ARGUMENT' && body?.error?.message === "Unable to parse range: 'Expanded Company Review'!A:ZZ";
