const sha256=s=>{const r=(n,x)=>x>>>n|x<<32-n,K=[],H=[],p={},u=new TextEncoder().encode(s);let q=2,c=0;while(c<64){if(!p[q]){for(let j=q*q;j<313;j+=q)p[j]=1;if(c<8)H[c]=(q**.5*2**32)|0;K[c++]=(q**(1/3)*2**32)|0}q++}const b=[...u,128];while(b.length%64!==56)b.push(0);const bits=u.length*8;b.push(0,0,0,0,(bits/2**24)&255,(bits>>>16)&255,(bits>>>8)&255,bits&255);for(let o=0;o<b.length;o+=64){const w=[];for(let i=0;i<16;i++)w[i]=b[o+i*4]<<24|b[o+i*4+1]<<16|b[o+i*4+2]<<8|b[o+i*4+3];for(let i=16;i<64;i++){const a=w[i-15],z=w[i-2];w[i]=(w[i-16]+(r(7,a)^r(18,a)^a>>>3)+w[i-7]+(r(17,z)^r(19,z)^z>>>10))|0}let [a,d,e,f,g,h,j,k]=H;for(let i=0;i<64;i++){const t1=(k+(r(6,g)^r(11,g)^r(25,g))+(g&h^~g&j)+K[i]+w[i])|0,t2=((r(2,a)^r(13,a)^r(22,a))+(a&d^a&e^d&e))|0;k=j;j=h;h=g;g=(f+t1)|0;f=e;e=d;d=a;a=(t1+t2)|0}H[0]=H[0]+a|0;H[1]=H[1]+d|0;H[2]=H[2]+e|0;H[3]=H[3]+f|0;H[4]=H[4]+g|0;H[5]=H[5]+h|0;H[6]=H[6]+j|0;H[7]=H[7]+k|0}return H.map(x=>(x>>>0).toString(16).padStart(8,'0')).join('')};
